planner_raw:
{
  "strategy": "This is a static visual question about a bottle illustration, so the minimal evidence is a representative frame from the bottle scene and a direct visual/spatial read of the bottle body versus the liquid level. Use one frame retrieval to anchor the image, then analyze that frame for the relative fill fraction.",
  "tool_calls": [
    {
      "step": 1,
      "tool": "frame_retriever",
      "arguments": {
        "video_path": "<VIDEO_PATH>",
        "query": "illustration of a glass bottle with blue liquid on a dark background, showing the full bottle and liquid level",
        "timestamps": null,
        "num_frames": 3
      },
      "purpose": "Retrieve the key frame(s) where the bottle illustration is clearly visible for direct inspection.",
      "depends_on": []
    },
    {
      "step": 2,
      "tool": "spatial_grounder",
      "arguments": {
        "frame_path": "<STEP_1:frames>",
        "timestamp": null,
        "query": "glass bottle body and the blue liquid region inside the bottle"
      },
      "purpose": "Ground the bottle outline and the liquid region in the retrieved frame bundle so the refiner can compare the liquid height to the bottle's usable interior height.",
      "depends_on": [
        1
      ]
    }
  ],
  "refinement_instructions": "Write the trace from scratch. Use the retrieved frame(s) from step 1 and the frame-level detections from step 2, not just any top-level summary. Identify the frame where the full bottle and liquid boundary are clearest. Compare the blue liquid region's height against the bottle body's interior height, ignoring the cap. Then map the observed proportion to the closest option among 2/3, 3/4, 3/5, 4/5, and 5/7. The rewritten trace should explicitly cite that the answer comes from visual proportion in the bottle illustration, not from inference or narration. If the grounded evidence is only approximate, state that the selected option is the closest matching fraction and update the final answer accordingly."
}
